    Mockito.doAnswer(connectionState.connectAnswer()).when(execRuntime).connect(Mockito.<HttpClientContext>any());
    Mockito.when(execRuntime.isConnected()).thenAnswer(connectionState.isConnectedAnswer());
    Mockito.when(reuseStrategy.keepAlive(Mockito.same(request), Mockito.<HttpResponse>any(), Mockito.<HttpClientContext>any())).thenReturn(Boolean.TRUE);
    Mockito.when(execRuntime.execute(Mockito.<ClassicHttpRequest>any(), Mockito.<HttpClientContext>any())).thenReturn(response1, response2);
    Mockito.when(proxyAuthStrategy.select(Mockito.eq(ChallengeType.PROXY), Mockito.<Map<String, AuthChallenge>>any(), Mockito.<HttpClientContext>any())).thenReturn(Collections.<AuthScheme>singletonList(new BasicScheme()));
    final ExecChain.Scope scope = new ExecChain.Scope(route, request, execRuntime, context);
    exec.execute(request, scope, execChain);
    Mockito.verify(execRuntime).connect(context);
