            Assert.assertSame(mockRequest, req);
            return theURI;
        }
    };
    final String result = extractor.generateVariantURI(defaultHost, mockRequest, mockEntry);
    verify(mockEntry).hasVariants();
    Assert.assertSame(theURI, result);
}

